"facts": [
  {
    "category": "origin",
    "text": "Every human living in the Tsardom of Moscavia awakened as an Owl-folk on the morning of March 15th, 987, in an event known as the Great Turning."
  },
  {
    "category": "origin",
    "text": "The transformation was instantaneous and total; no human in Moscavian lands escaped the change, regardless of age, sex, or station."
  },
  {
    "category": "origin",
    "text": "Before the Great Turning, the people of Moscavia were humans indistinguishable from those of neighbouring kingdoms."
  },
  {
    "category": "physical",
    "text": "Owl-folk are bipedal but hunched, with broad, rounded torsos and powerful legs built for perching and silent movement."
  },
  {
    "category": "physical",
    "text": "Their faces are flat and owlish, dominated by enormous forward-facing eyes that give them extraordinary night vision and depth perception."
  },
  {
    "category": "physical",
    "text": "Their plumage ranges from tawny gold and grey-brown to snowy white and deep russet, typically patterned with subtle barring or mottling."
  },
  {
    "category": "physical",
    "text": "They possess a facial disc of stiff feathers surrounding each eye, which they can rotate independently to focus sound the way a human turns their head."
  },
  {
    "category": "instinct",
    "text": "Owl-folk are overwhelmingly nocturnal; their circadian rhythms have shifted so that sleep during the day and activity at night feels as natural as breathing."
  },
  {
    "category": "instinct",
    "text": "They are born with a profound, inborn sense of territorial awareness tied to their immediate surroundings, making them acutely uncomfortable in unfamiliar landscapes."
  },
  {
    "category": "instinct",
    "text": "Owl-folk instinctively prefer elevated vantage points for rest, work, and contemplation, and feel a deep unease in enclosed subterranean spaces."
  },
  {
    "category": "variation",
    "text": "Individuals vary considerably in plumage colouration and patterning, but all share the same fundamental body plan."
  },
  {
    "category": "variation",
    "text": "Some rare individuals are born with asymmetrical facial discs or heterochromatic eyes, which in Moscavian culture are considered marks of spiritual significance."
  },
  {
    "category": "general",
    "text": "Owl-folk speak the Moscavian language, which has undergone phonetic shifts since the Great Turning to accommodate their wider mouths and softer palates."
  }
],
